var t=`1016-mango-sticky-rice`;var s=`world-1016`;var a=`TH`;var r=`southeast-asia`;var o=8;var n=281;var l={en:`Mango Sticky Rice`,ua:`Клейкий рис із манго`};var u={en:`Mango Sticky Rice is a dish from Thailand prepared with glutinous rice, coconut milk, mango, white sesame seeds. This is a home-scale version with measured ingredients in the individual steps where they are used. Use glutinous sticky rice; regular jasmine rice is not a suitable substitute.`,ua:`Клейкий рис із манго, страва кухні країни Таїланд, яку готують із таких продуктів: клейкий рис, кокосове молоко, манго, білий кунжут. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Використовуйте клейкий рис; звичайний жасминовий не є рівноцінною заміною.`};var c=[{en:`Soak the measured rice or noodles in clean cool water for about 240 minutes, then drain and proceed to the specified cooking step.`,ua:`Замочіть зазначені рис або локшину в чистій прохолодній воді близько 240 хвилин, злийте і переходьте до подальшого готування.`,t:[`rice-soaking`],m:240,i:[[`glutinous-rice`,450,`g`],[`water`,900,`ml`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 30 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 30 хвилин до готовності.`,t:[`steaming`],m:30,i:[]},{en:`Warm coconut milk with palm sugar and salt, then pour most of it over the freshly steamed sticky rice; cover and let absorb before serving.`,ua:`Нагрійте кокосове молоко з пальмовим цукром і сіллю, залийте ним більшу частину щойно пропареного клейкого рису та накрийте для просочення.`,t:[`reducing-sauce`],m:7,i:[[`coconut-milk`,390,`ml`],[`palm-sugar`,100,`g`],[`table-salt`,3,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`mango`,3,`pcs`],[`white-sesame-seeds`,20,`g`]]}];var m={slug:t,id:s,country:`TH`,region:r,servings:8,minutes:281,title:l,text:u,steps:c};export{a as country,m as default,s as id,n as minutes,r as region,o as servings,t as slug,c as steps,u as text,l as title};